    cnt = Counter(x for row in grid for x in row)
    nonzeros = sorted([c for c, n in cnt.items() if c > 0], key=lambda c: cnt[c])

    if len(nonzeros) < 2:
        return [row[:] for row in grid]

    fill_color = nonzeros[0]
    secondary_color = nonzeros[1]

    H, W = len(grid), len(grid[0])
